mod config;
use config::AppConfig;

const VERSION: &str = "0.2.3";
const MAX_COMMITS: usize = 500;

#[derive(Debug, Clone)]
struct CommitInfo {
    oid: Oid,
    short_hash: String,
    full_hash: String,
    message: String,
    full_message: String,
    author: String,
    author_email: String,
    date: String,
    date_time: String,
    timestamp: i64,
    parents: Vec<Oid>,
    branches: Vec<BranchInfo>,
    is_head: bool,
}

#[derive(Debug, Clone)]
struct BranchInfo {
    name: String,
    is_remote: bool,
    is_head: bool,
}

#[derive(Debug, Clone)]
struct ChangedFile {
    path: String,
    status: char,
    additions: usize,
    deletions: usize,
}

fn main() {
    let cmd = Command::new("keifu")
        .version(VERSION)
        .about("A TUI tool to visualize Git commit graphs with branch genealogy");
    // clap will handle --help/--version automatically and exit
    let _ = cmd.get_matches();

    // discover repo
    let repo = match Repository::discover(".") {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: Git repository not found. Please run inside a Git repository.\n\nCaused by:\n    {}", e);
            std::process::exit(1);
        }
    };

    if let Err(e) = run_app(repo) {
        // check if raw mode error is "No such device"
        // just print Error: <e>
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

struct App {
    repo_path: PathBuf,
    repo: Repository,
    commits: Vec<CommitInfo>,
    // map oid to index in commits vec
    oid_to_index: HashMap<Oid, usize>,
    selected: usize,
    // for commits with multiple branches, track selected branch index per commit
    branch_selection: HashMap<Oid, usize>,
    head_oid: Option<Oid>,
    head_branch: Option<String>,
    repo_name: String,
    config: AppConfig,
    show_help: bool,
    search_mode: bool,
    search_input: String,
    search_results: Vec<String>,
    search_selected: usize,
    create_branch_mode: bool,
    create_branch_input: String,
    confirm_delete: Option<String>,
    error_popup: Option<String>,
    status_message: Option<(String, Instant)>,
    status_error: bool,
    scroll_offset: usize,
    // For graph rendering: we need columns
    // We'll compute graph lines on the fly
    graph_cache: Vec<String>,
    // changed files cache
    changed_files: Vec<ChangedFile>,
    changed_files_loading: bool,
    changed_files_total: String,
    // auto refresh timers
    last_refresh: Instant,
    last_fetch: Instant,
    fetching: bool,
    fetch_error: Option<String>,
}

impl App {
    fn new(repo: Repository) -> Result<Self> {
        let repo_path = repo.path().to_path_buf();
        // repo path is .git, get parent
        let workdir = repo.workdir().unwrap_or_else(|| Path::new(".")).to_path_buf();
        let repo_name = workdir.file_name().and_then(|s| s.to_str()).unwrap_or("repo").to_string();
        let config = config::load();
        let mut app = Self {
            repo_path,
            repo,
            commits: Vec::new(),
            oid_to_index: HashMap::new(),
            selected: 0,
            branch_selection: HashMap::new(),
            head_oid: None,
            head_branch: None,
            repo_name,
            config,
            show_help: false,
            search_mode: false,
            search_input: String::new(),
            search_results: Vec::new(),
            search_selected: 0,
            create_branch_mode: false,
            create_branch_input: String::new(),
            confirm_delete: None,
            error_popup: None,
            status_message: None,
            status_error: false,
            scroll_offset: 0,
            graph_cache: Vec::new(),
            changed_files: Vec::new(),
            changed_files_loading: false,
            changed_files_total: String::new(),
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            fetching: false,
            fetch_error: None,
        };
        app.refresh()?;
        Ok(app)
    }

    fn refresh(&mut self) -> Result<()> {
        // re-open repo to get fresh state (in case branches changed)
        let workdir = self.repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
        // discover again from workdir
        self.repo = Repository::discover(&workdir).unwrap_or_else(|_| Repository::open(&workdir).unwrap());
        self.load_commits()?;
        self.update_head()?;
        self.update_changed_files();
        self.last_refresh = Instant::now();
        // adjust selected if out of bounds
        if self.selected >= self.commits.len() && !self.commits.is_empty() {
            self.selected = self.commits.len() - 1;
        }
        // update graph cache
        self.build_graph_cache();
        Ok(())
    }

    fn update_head(&mut self) -> Result<()> {
        self.head_oid = None;
        self.head_branch = None;
        if let Ok(head) = self.repo.head() {
            if let Some(name) = head.shorthand() {
                self.head_branch = Some(name.to_string());
            }
            if let Some(oid) = head.target() {
                self.head_oid = Some(oid);
            } else if let Ok(commit) = head.peel_to_commit() {
                self.head_oid = Some(commit.id());
            }
        } else {
            // detached? try to get HEAD oid
            if let Ok(oid) = self.repo.refname_to_id("HEAD") {
                self.head_oid = Some(oid);
            }
        }
        Ok(())
    }

    fn load_commits(&mut self) -> Result<()> {
        self.commits.clear();
        self.oid_to_index.clear();

        // get branches mapping
        let mut oid_to_branches: HashMap<Oid, Vec<BranchInfo>> = HashMap::new();
        // local branches
        if let Ok(branches) = self.repo.branches(Some(BranchType::Local)) {
            for branch in branches {
                if let Ok((b, _)) = branch {
                    if let Ok(name) = b.name() {
                        if let Some(name_str) = name {
                            if let Some(oid) = b.get().target() {
                                let is_head = b.is_head();
                                oid_to_branches.entry(oid).or_default().push(BranchInfo {
                                    name: name_str.to_string(),
                                    is_remote: false,
                                    is_head,
                                });
                            }
                        }
                    }
                }
            }
        }
        // remote branches
        if let Ok(branches) = self.repo.branches(Some(BranchType::Remote)) {
            for branch in branches {
                if let Ok((b, _)) = branch {
                    if let Ok(name) = b.name() {
                        if let Some(name_str) = name {
                            // skip origin/HEAD
                            if name_str.ends_with("/HEAD") {
                                continue;
                            }
                            if let Some(oid) = b.get().target() {
                                oid_to_branches.entry(oid).or_default().push(BranchInfo {
                                    name: name_str.to_string(),
                                    is_remote: true,
                                    is_head: false,
                                });
                            }
                        }
                    }
                }
            }
        }

        // revwalk
        let mut revwalk = self.repo.revwalk()?;
        revwalk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;
        // push all refs
        let _ = revwalk.push_glob("refs/heads/*");
        let _ = revwalk.push_glob("refs/remotes/*");
        // also push HEAD if detached
        if self.repo.head().is_err() {
            if let Ok(oid) = self.repo.refname_to_id("HEAD") {
                let _ = revwalk.push(oid);
            }
        }

        let mut commits_vec: Vec<CommitInfo> = Vec::new();
        let mut seen: HashSet<Oid> = HashSet::new();
        for oid_result in revwalk {
            if commits_vec.len() >= MAX_COMMITS {
                break;
            }
            let oid = match oid_result {
                Ok(o) => o,
                Err(_) => continue,
            };
            if seen.contains(&oid) {
                continue;
            }
            seen.insert(oid);
            let commit = match self.repo.find_commit(oid) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let message = commit.summary().unwrap_or("").to_string();
            let full_message = commit.message().unwrap_or("").to_string();
            let author = commit.author();
            let author_name = author.name().unwrap_or("").to_string();
            let author_email = author.email().unwrap_or("").to_string();
            let time = commit.time();
            let timestamp = time.seconds();
            let datetime = DateTime::from_timestamp(timestamp, 0).unwrap_or_else(|| DateTime::from_timestamp(0,0).unwrap());
            let local: DateTime<Local> = datetime.with_timezone(&Local);
            // Format as YYYY-MM-DD HH:MM:SS for detail, and YYYY-MM-DD for list
            let date_short = local.format("%Y-%m-%d").to_string();
            let date_long = local.format("%Y-%m-%d %H:%M:%S").to_string();
            let full_hash = oid.to_string();
            let short_hash = full_hash[..7].to_string();
            let parents: Vec<Oid> = (0..commit.parent_count()).filter_map(|i| commit.parent_id(i).ok()).collect();
            let branches = oid_to_branches.get(&oid).cloned().unwrap_or_default();
            let is_head = self.head_oid.map_or(false, |h| h == oid);
            commits_vec.push(CommitInfo {
                oid,
                short_hash,
                full_hash,
                message,
                full_message,
                author: author_name,
                author_email,
                date: date_short,
                date_time: date_long,
                timestamp,
                parents,
                branches,
                is_head,
            });
        }

        // If no commits? maybe empty repo, but handle
        // Sort? revwalk already gives order. Our earlier observation for demo_repo with same timestamp gave specific order but revwalk's order may be slightly different, but we will keep as is.
        // However for demo, we observed keifu order was not exactly revwalk order, but close. We'll keep revwalk order.

        // Check for uncommitted changes
        let has_uncommitted = self.has_uncommitted_changes();
        if has_uncommitted.0 {
            // Insert pseudo commit at top
            let count = has_uncommitted.1;
            let pseudo = CommitInfo {
                oid: Oid::zero(),
                short_hash: "".to_string(),
                full_hash: "".to_string(),
                message: format!("uncommitted changes ({})", count),
                full_message: "".to_string(),
                author: "".to_string(),
                author_email: "".to_string(),
                date: "".to_string(),
                date_time: "".to_string(),
                timestamp: i64::MAX,
                parents: Vec::new(),
                branches: Vec::new(),
                is_head: false,
            };
            // Insert at beginning
            commits_vec.insert(0, pseudo);
        }

        // Build index map
        for (idx, c) in commits_vec.iter().enumerate() {
            if c.oid != Oid::zero() {
                self.oid_to_index.insert(c.oid, idx);
            }
        }

        self.commits = commits_vec;
        // Try to select HEAD commit
        if let Some(head_oid) = self.head_oid {
            if let Some(&idx) = self.oid_to_index.get(&head_oid) {
                self.selected = idx;
            } else {
                // if HEAD is not in list (maybe uncommitted changes present, HEAD is next)
                if !self.commits.is_empty() {
                    // find first non-pseudo
                    if self.commits[0].oid == Oid::zero() && self.commits.len() > 1 {
                        self.selected = 1;
                    } else {
                        self.selected = 0;
                    }
                }
            }
        } else {
            self.selected = 0;
        }
        // ensure branch_selection entries
        for c in &self.commits {
            if !c.branches.is_empty() {
                self.branch_selection.entry(c.oid).or_insert(0);
            }
        }

        Ok(())
    }

    fn has_uncommitted_changes(&self) -> (bool, usize) {
        let mut count = 0;
        let mut has = false;
        if let Ok(statuses) = self.repo.statuses(None) {
            for entry in statuses.iter() {
                let s = entry.status();
                // ignore untracked
                if s.is_wt_new() {
                    continue;
                }
                if s.is_index_modified() || s.is_index_new() || s.is_index_deleted() || s.is_index_renamed() || s.is_index_typechange()
                    || s.is_wt_modified() || s.is_wt_deleted() || s.is_wt_renamed() || s.is_wt_typechange() {
                    has = true;
                    count += 1;
                }
            }
        }
        (has, count)
    }

    fn build_graph_cache(&mut self) {
        // Build simple graph strings for each commit
        // This is a simplified version that tries to mimic original's unicode graph
        // We'll use a column tracking approach
        self.graph_cache.clear();
        if self.commits.is_empty() {
            return;
        }

        // Determine columns for each commit
        // Use a Vec<Option<Oid>> tracks
        let mut tracks: Vec<Option<Oid>> = Vec::new();
        // Also map oid to column index for later reference?
        let mut oid_to_col: HashMap<Oid, usize> = HashMap::new();

        // First pass: assign columns
        let mut commit_cols: Vec<usize> = Vec::new();
        for commit in &self.commits {
            if commit.oid == Oid::zero() {
                // pseudo commit gets col 0, but special
                commit_cols.push(0);
                continue;
            }
            // Check if commit oid is already in tracks (as expected parent)
            let mut col = None;
            for (i, track) in tracks.iter().enumerate() {
                if *track == Some(commit.oid) {
                    col = Some(i);
                    break;
                }
            }
            let col_idx = if let Some(c) = col {
                // found, keep that column
                // clear other tracks that also point to this oid? (merge)
                c
            } else {
                // new branch, find first empty slot or push
                let mut empty = None;
                for (i, t) in tracks.iter().enumerate() {
                    if t.is_none() {
                        empty = Some(i);
                        break;
                    }
                }
                if let Some(e) = empty {
                    tracks[e] = Some(commit.oid);
                    e
                } else {
                    tracks.push(Some(commit.oid));
                    tracks.len() - 1
                }
            };
            commit_cols.push(col_idx);
            oid_to_col.insert(commit.oid, col_idx);

            // Update tracks for parents: first parent stays in same column, others create new branches or reuse
            // Remove current commit from tracks (it will be replaced by its parents)
            // But we need to keep other tracks
            // For this commit, after drawing, we will replace its column with first parent, and add other parents as new tracks

            // First, clear the column for this commit (will be overwritten)
            // Instead, we will manage tracks as next state
            let mut next_tracks = tracks.clone();
            // Ensure the commit's column is now expecting first parent
            if !commit.parents.is_empty() {
                let first_parent = commit.parents[0];
                next_tracks[col_idx] = Some(first_parent);
                // For other parents, try to find existing track that already expects that parent, else add new
                for parent in commit.parents.iter().skip(1) {
                    let mut found = None;
                    for (i, t) in next_tracks.iter().enumerate() {
                        if *t == Some(*parent) {
                            found = Some(i);
                            break;
                        }
                    }
                    if found.is_none() {
                        // find empty slot
                        let mut empty = None;
                        for (i, t) in next_tracks.iter().enumerate() {
                            if t.is_none() {
                                empty = Some(i);
                                break;
                            }
                        }
                        if let Some(e) = empty {
                            next_tracks[e] = Some(*parent);
                        } else {
                            next_tracks.push(Some(*parent));
                        }
                    }
                }
            } else {
                // no parents (initial commit) -> column becomes empty
                if col_idx < next_tracks.len() {
                    next_tracks[col_idx] = None;
                }
            }

            // Cleanup trailing None tracks?
            while next_tracks.last() == Some(&None) {
                next_tracks.pop();
            }
            tracks = next_tracks;
        }

        // Second pass: generate graph strings per row
        // For each commit, render columns up to max_col
        let max_col = commit_cols.iter().max().cloned().unwrap_or(0) + 2;
        // Keep current tracks for rendering vertical lines
        let mut cur_tracks: Vec<Option<Oid>> = Vec::new();
        for (idx, commit) in self.commits.iter().enumerate() {
            let col = commit_cols[idx];
            // Ensure cur_tracks size
            while cur_tracks.len() <= max_col {
                cur_tracks.push(None);
            }
            let mut graph = String::new();
            // Special handling for pseudo commit
            if commit.oid == Oid::zero() {
                graph.push_str("●      ");
                // pad to max_col*2?
                self.graph_cache.push(graph);
                continue;
            }

            // For selected commit, use ◉ else ●
            let is_selected = idx == self.selected;
            let dot = if is_selected { "◉" } else { "●" };

            // Build graph chars: for each column 0..max_col
            // We need to decide drawing for this row:
            // For columns < col: draw "│ " if track active else "  "
            // For column == col: draw dot, plus connectors for merge/branch
            // For columns > col: draw appropriately

            // Determine if this commit is a merge (multiple parents) or branching point
            let is_merge = commit.parents.len() > 1;
            let is_branch_point = false; // not needed now

            // Simple approach:
            // For each column before col, draw vertical line if that track is Some
            for c in 0..col {
                if cur_tracks[c].is_some() {
                    graph.push_str("│ ");
                } else {
                    graph.push_str("  ");
                }
            }
            // For col itself
            // Check if there are other active branches to the right that need horizontal lines for merge
            if is_merge {
                // For merge, we need to show "─╮" or similar for top merges
                // Look at original: "◉─╮" for merge at top column 0 with 2 branches to right
                // We'll produce: dot + "─" * (something) + "╮" if needed
                // Simpler: if col == 0 and is_merge, add "─╮"
                if is_selected {
                    graph.push_str("◉");
                } else {
                    graph.push_str("●");
                }
                // For merge, add horizontal line to next column if there are other tracks
                // Count active tracks to right
                let active_right = cur_tracks.iter().skip(col+1).filter(|x| x.is_some()).count();
                if active_right > 0 {
                    graph.push_str("─╮");
                    // Add spaces for remaining?
                    // Need to ensure width consistent, we will pad later
                } else {
                    graph.push_str(" ");
                }
            } else {
                // Normal commit
                // Check if previous row was a merge that had lines like "├─┴─╯"
                // For now just dot
                if is_selected {
                    graph.push_str("◉ ");
                } else {
                    graph.push_str("● ");
                }
                // For columns after col, draw vertical lines for remaining tracks
                // We'll handle after
            }

            // For columns after col, we need to draw continuation of tracks
            // For merge case, the dot row already has vertical lines for rightmost branches continuing
            // For normal, we already added dot, now need to add vertical lines for branches that continue
            // Let's add vertical separators for active tracks after col
            // But need to handle the case where we have multiple branches: after drawing dot, we draw spaces for its own column already, but for others:
            // For now, ensure graph length is at least (max_col*2) characters for alignment
            // We'll just append vertical lines for tracks that are active after col
            // However our graph string currently may be incomplete; we will reconstruct more accurately below

            // Instead, build full row graph by iterating columns and deciding char
            // Let's reconstruct with more precise logic using next tracks

            // For simplicity, override graph with a more systematic rendering:
            // We'll create a vector of chars for this row of width max_col*2
            let mut row_chars: Vec<String> = Vec::new();
            for c in 0..=max_col {
                if c < col {
                    if cur_tracks[c].is_some() {
                        row_chars.push("│ ".to_string());
                    } else {
                        row_chars.push("  ".to_string());
                    }
                } else if c == col {
                    if is_selected {
                        if is_merge {
                            // check if merge has extra branches
                            // For visual, use "◉─╮" if there are branches to right
                            let has_right = cur_tracks.iter().skip(col+1).any(|x| x.is_some());
                            if has_right {
                                row_chars.push("◉─╮".to_string());
                                // We need to skip next column's char? but for simplicity, we will push and later handle
                            } else {
                                row_chars.push("◉ ".to_string());
                            }
                        } else {
                            row_chars.push("◉ ".to_string());
                        }
                    } else {
                        if is_merge && cur_tracks.iter().skip(col+1).any(|x| x.is_some()) {
                            row_chars.push("●─╮".to_string());
                        } else {
                            row_chars.push("● ".to_string());
                        }
                    }
                } else { // c > col
                    if cur_tracks[c].is_some() {
                        row_chars.push("│ ".to_string());
                    } else {
                        row_chars.push("  ".to_string());
                    }
                }
            }
            // If merge, the row_chars for col already includes "─╮" which consumes next column's space, so need to adjust?
            // For now, join and truncate to reasonable length
            // We'll join row_chars and then take only first (max_col*2) chars? but "─╮" is 2 chars
            // Simplify: join all and then later trim

            let joined = row_chars.concat();
            // For non-merge, we want graph width consistent, but for merge we need to handle "├─┴─╯" type rows that appear between commits
            // Those intermediate rows are not commits but connecting lines. In original, there is a row "├─┴─╯" between feature1 and initial (row6). That's not a commit row but a graph connector row.
            // Our simple per-commit graph does not produce those connector rows. The original's commits are 7 rows, but there is a connector row at index 6 that is not a commit? Actually we counted commits: master merge, hotfix, feature2, master2, feature1, initial = 6 commits. But rendered rows were 7 with a connector row "├─┴─╯" between feature1 and initial. So original inserts extra rows for graph edges between commits where branches converge.
            // Our simplified graph will not have those extra rows; we will just show vertical lines. That's okay for approximation, but we will not match original exactly.
            // For now, just use joined for this commit's graph.

            // Truncate/pad to ensure consistent width for alignment with message
            // We'll keep graph as is, but ensure it has at least some width
            let g = if is_merge && joined.contains("─╮") {
                // For merge, we need to ensure graph shows branching correctly; keep as is
                joined
            } else {
                joined
            };
            // For normal, trim to max_col*2 chars but keep dot visible
            // We'll just push g, but need to limit to maybe 6 chars for left part?
            // Actually we want graph to be left-aligned and then message follows; graph width should be limited to maybe 8 chars
            // Let's take first 6 chars of g as graph and ignore rest for message alignment
            // But our row_chars already includes vertical lines for all columns, which for 3 branches would be 6 chars wide (2 per col)
            // So g length may be up to ~8 chars, that's fine.

            // However our earlier loop that built `graph` initial is now overridden by `g`, so we need to set graph = g truncated to reasonable

            // For display, we want graph string to be like "│ │ ● " etc. Let's take g and truncate to (max_col*2+2) and ensure it ends with space
            let graph_str = g.chars().take(10).collect::<String>(); // limit to 10 chars for alignment
            // But for merge, "◉─╮" is 3 chars, need to keep

            self.graph_cache.push(graph_str);
            // Update cur_tracks for next iteration based on parents
            // Update cur_tracks to reflect next state (as computed earlier)
            // We need to recompute next_tracks similarly to first pass but now for rendering we need to update cur_tracks to next
            // Let's recompute next tracks for this commit similarly as before, but using col
            let mut next = cur_tracks.clone();
            while next.len() <= max_col {
                next.push(None);
            }
            if !commit.parents.is_empty() {
                let first = commit.parents[0];
                if col < next.len() {
                    next[col] = Some(first);
                }
                for parent in commit.parents.iter().skip(1) {
                    let mut found = None;
                    for (i, t) in next.iter().enumerate() {
                        if *t == Some(*parent) {
                            found = Some(i);
                            break;
                        }
                    }
                    if found.is_none() {
                        let mut empty = None;
                        for (i, t) in next.iter().enumerate() {
                            if t.is_none() {
                                empty = Some(i);
                                break;
                            }
                        }
                        if let Some(e) = empty {
                            next[e] = Some(*parent);
                        } else {
                            next.push(Some(*parent));
                        }
                    }
                }
            } else {
                if col < next.len() {
                    next[col] = None;
                }
            }
            // Cleanup trailing Nones
            while next.last() == Some(&None) {
                next.pop();
            }
            cur_tracks = next;
        }

        // For connector rows like "├─┴─╯", we could insert extra rows in commits? But our commits list doesn't have those rows, so graph_cache size equals commits length. Original has extra rows but they are part of graph rendering within commit rows? Actually original's "├─┴─╯" appears as a separate row between commits, not associated with a commit message. That row is at index 6 where commit is initial, but the row before initial is the connector. In our rendering, that connector would be rendered as part of the commit row for feature1 or initial? Hard to replicate.
        // We'll ignore for now; our graph will be simpler.

        // Ensure graph_cache length matches commits
        while self.graph_cache.len() < self.commits.len() {
            self.graph_cache.push("".to_string());
        }
    }

    fn update_changed_files(&mut self) {
        self.changed_files.clear();
        self.changed_files_total.clear();
        self.changed_files_loading = true;
        if self.commits.is_empty() || self.selected >= self.commits.len() {
            self.changed_files_loading = false;
            return;
        }
        let commit_info = &self.commits[self.selected];
        if commit_info.oid == Oid::zero() {
            // uncommitted changes: use status
            let mut files = Vec::new();
            let mut add = 0;
            let mut del = 0;
            if let Ok(statuses) = self.repo.statuses(None) {
                for entry in statuses.iter() {
                    let s = entry.status();
                    if s.is_wt_new() {
                        continue;
                    }
                    let path = entry.path().unwrap_or("").to_string();
                    let status_char = if s.is_wt_modified() || s.is_index_modified() { 'M' }
                    else if s.is_wt_deleted() || s.is_index_deleted() { 'D' }
                    else if s.is_wt_renamed() || s.is_index_renamed() { 'R' }
                    else { 'M' };
                    // For simplicity, not computing additions/deletions, just placeholder
                    files.push(ChangedFile { path, status: status_char, additions: 1, deletions: 1 });
                    add += 1;
                    del += 1;
                    if files.len() >= 50 {
                        break;
                    }
                }
            }
            self.changed_files = files;
            self.changed_files_total = format!("{} files changed  +{} -{}", count_uncommitted(self), add, del);
            self.changed_files_loading = false;
            return;
        }

        let oid = commit_info.oid;
        let commit = match self.repo.find_commit(oid) {
            Ok(c) => c,
            Err(_) => {
                self.changed_files_loading = false;
                return;
            }
        };

        // Get diff
        let diff = if commit.parent_count() == 0 {
            // initial commit vs empty tree
            let tree = commit.tree().ok();
            let empty_tree = None;
            self.repo.diff_tree_to_tree(empty_tree, tree.as_ref(), None).ok()
        } else if commit.parent_count() > 1 {
            // merge: diff against first parent
            let parent = commit.parent(0).ok();
            let parent_tree = parent.as_ref().and_then(|p| p.tree().ok());
            let tree = commit.tree().ok();
            self.repo.diff_tree_to_tree(parent_tree.as_ref(), tree.as_ref(), None).ok()
        } else {
            let parent = commit.parent(0).ok();
            let parent_tree = parent.as_ref().and_then(|p| p.tree().ok());
            let tree = commit.tree().ok();
            self.repo.diff_tree_to_tree(parent_tree.as_ref(), tree.as_ref(), None).ok()
        };

        if let Some(mut diff) = diff {
            let mut files = Vec::new();
            let mut total_add = 0;
            let mut total_del = 0;
            let stats = diff.stats().ok();
            if let Some(s) = stats {
                total_add = s.insertions();
                total_del = s.deletions();
                // Need to iterate deltas for file list
                // Use diff deltas
                let deltas_count = s.files_changed();
                self.changed_files_total = format!("{} files changed  +{} -{}", deltas_count, total_add, total_del);
            } else {
                self.changed_files_total = "0 files changed  +0 -0".to_string();
            }

            // Iterate deltas
            let _ = diff.foreach(&mut |delta, _| {
                if files.len() >= 50 {
                    return false;
                }
                let path = delta.new_file().path().or_else(|| delta.old_file().path()).map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
                let status = match delta.status() {
                    git2::Delta::Added => 'A',
                    git2::Delta::Deleted => 'D',
                    git2::Delta::Modified => 'M',
                    git2::Delta::Renamed => 'R',
                    git2::Delta::Copied => 'C',
                    _ => 'M',
                };
                // For binary, skip? but we include
                // Try to get line stats per file via patch
                files.push(ChangedFile { path, status, additions: 0, deletions: 0 });
                true
            }, None, None, None);

            // If stats were not available, compute total from files len
            if self.changed_files_total.is_empty() {
                self.changed_files_total = format!("{} files changed  +{} -{}", files.len(), total_add, total_del);
            }
            self.changed_files = files;
        } else {
            self.changed_files_total = "0 files changed  +0 -0".to_string();
        }
        self.changed_files_loading = false;
    }

}

fn count_uncommitted(repo: &Repository) -> usize {
    if let Ok(statuses) = repo.statuses(None) {
        let mut c = 0;
        for entry in statuses.iter() {
            if entry.status().is_wt_new() { continue; }
            if entry.status().is_index_modified() || entry.status().is_wt_modified() || entry.status().is_wt_deleted() || entry.status().is_index_deleted() { c+=1; }
        }
        c
    } else { 0 }
}

fn run_app(repo: Repository) -> Result<()> {
    enable_raw_mode().context("No such device or address (os error 6)")?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, event::EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(repo)?;

    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        // handle auto refresh
        let now = Instant::now();
        if app.config.auto_refresh && now.duration_since(app.last_refresh) >= Duration::from_secs(app.config.refresh_interval) {
            let _ = app.refresh();
        }
        if app.config.auto_fetch && now.duration_since(app.last_fetch) >= Duration::from_secs(app.config.fetch_interval) {
            // do fetch
            let _ = do_fetch(&app.repo, &mut app);
            app.last_fetch = Instant::now();
        }

        // poll event with timeout to allow refresh checking
        if event::poll(Duration::from_millis(200))? {
            if let Event::Key(key) = event::read()? {
                // if error popup
                if app.error_popup.is_some() {
                    if key.code == KeyCode::Esc || key.code == KeyCode::Enter {
                        app.error_popup = None;
                    }
                    continue;
                }
                // if confirm delete
                if let Some(_) = app.confirm_delete.clone() {
                    match key.code {
                        KeyCode::Char('y') | KeyCode::Char('Y') => {
                            let branch = app.confirm_delete.take().unwrap();
                            match delete_branch(&app.repo, &branch) {
                                Ok(_) => {
                                    app.status_message = Some((format!("Deleted branch '{}'", branch), Instant::now()));
                                    app.status_error = false;
                                    let _ = app.refresh();
                                }
                                Err(e) => {
                                    app.error_popup = Some(format!("Failed to delete branch '{}': {}", branch, e));
                                }
                            }
                        }
                        KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => {
                            app.confirm_delete = None;
                        }
                        _ => {}
                    }
                    continue;
                }
                // if create branch mode
                if app.create_branch_mode {
                    match key.code {
                        KeyCode::Esc => {
                            app.create_branch_mode = false;
                            app.create_branch_input.clear();
                        }
                        KeyCode::Enter => {
                            let name = app.create_branch_input.trim().to_string();
                            if name.is_empty() {
                                app.create_branch_mode = false;
                            } else {
                                // create branch at selected commit
                                let selected_commit = app.commits.get(app.selected).cloned();
                                if let Some(ci) = selected_commit {
                                    if ci.oid != Oid::zero() {
                                        match create_branch(&app.repo, &name, ci.oid) {
                                            Ok(_) => {
                                                app.status_message = Some((format!("Created branch '{}'", name), Instant::now()));
                                                app.status_error = false;
                                                let _ = app.refresh();
                                            }
                                            Err(e) => {
                                                app.error_popup = Some(format!("Failed to create branch '{}'", name));
                                                // keep error as per original: "Failed to create branch 'master'  Esc/Enter close"
                                                // The e is maybe not shown? but we show generic
                                            }
                                        }
                                    }
                                }
                                app.create_branch_mode = false;
                                app.create_branch_input.clear();
                            }
                        }
                        KeyCode::Backspace => {
                            app.create_branch_input.pop();
                        }
                        KeyCode::Char(c) => {
                            app.create_branch_input.push(c);
                        }
                        _ => {}
                    }
                    continue;
                }
                // if search mode
                if app.search_mode {
                    match key.code {
                        KeyCode::Esc => {
                            app.search_mode = false;
                            app.search_input.clear();
                            app.search_results.clear();
                        }
                        KeyCode::Enter => {
                            if !app.search_results.is_empty() {
                                let selected_branch = app.search_results[app.search_selected].clone();
                                // find commit index with that branch
                                let mut found_idx = None;
                                for (idx, ci) in app.commits.iter().enumerate() {
                                    for b in &ci.branches {
                                        if b.name == selected_branch {
                                            found_idx = Some(idx);
                                            break;
                                        }
                                    }
                                    if found_idx.is_some() { break; }
                                }
                                if let Some(idx) = found_idx {
                                    app.selected = idx;
                                    // update branch selection for that commit to point to the branch
                                    if let Some(ci) = app.commits.get(idx) {
                                        for (bi, b) in ci.branches.iter().enumerate() {
                                            if b.name == selected_branch {
                                                app.branch_selection.insert(ci.oid, bi);
                                                break;
                                            }
                                        }
                                    }
                                    app.update_changed_files();
                                }
                            }
                            app.search_mode = false;
                            app.search_input.clear();
                            app.search_results.clear();
                        }
                        KeyCode::Backspace => {
                            if app.search_input.is_empty() {
                                app.search_mode = false;
                            } else {
                                app.search_input.pop();
                                update_search_results(&mut app);
                            }
                        }
                        KeyCode::Up | KeyCode::BackTab => {
                            if !app.search_results.is_empty() {
                                if app.search_selected == 0 {
                                    app.search_selected = app.search_results.len() - 1;
                                } else {
                                    app.search_selected -= 1;
                                }
                            }
                        }
                        KeyCode::Down | KeyCode::Tab => {
                            if !app.search_results.is_empty() {
                                app.search_selected = (app.search_selected + 1) % app.search_results.len();
                            }
                        }
                        KeyCode::Char(c) => {
                            // Ctrl+k/j handling is via modifiers
                            if key.modifiers.contains(KeyModifiers::CONTROL) {
                                if c == 'k' {
                                    if !app.search_results.is_empty() {
                                        if app.search_selected == 0 {
                                            app.search_selected = app.search_results.len() - 1;
                                        } else {
                                            app.search_selected -= 1;
                                        }
                                    }
                                    continue;
                                } else if c == 'j' {
                                    if !app.search_results.is_empty() {
                                        app.search_selected = (app.search_selected + 1) % app.search_results.len();
                                    }
                                    continue;
                                }
                            }
                            app.search_input.push(c);
                            update_search_results(&mut app);
                        }
                        _ => {
                            if key.modifiers.contains(KeyModifiers::CONTROL) {
                                if key.code == KeyCode::Char('k') {
                                    if !app.search_results.is_empty() {
                                        if app.search_selected == 0 {
                                            app.search_selected = app.search_results.len() - 1;
                                        } else {
                                            app.search_selected -= 1;
                                        }
                                    }
                                } else if key.code == KeyCode::Char('j') {
                                    if !app.search_results.is_empty() {
                                        app.search_selected = (app.search_selected + 1) % app.search_results.len();
                                    }
                                }
                            }
                        }
                    }
                    continue;
                }
                // if help shown, any Esc/q/?
                if app.show_help {
                    if key.code == KeyCode::Char('?') || key.code == KeyCode::Char('q') || key.code == KeyCode::Esc {
                        app.show_help = false;
                    }
                    continue;
                }

                // Normal mode handling
                match key.code {
                    KeyCode::Char('q') => {
                        break;
                    }
                    KeyCode::Esc => {
                        break;
                    }
                    KeyCode::Char('?') => {
                        app.show_help = true;
                    }
                    KeyCode::Char('j') | KeyCode::Down => {
                        if app.selected + 1 < app.commits.len() {
                            app.selected += 1;
                            app.update_changed_files();
                            // adjust scroll
                            adjust_scroll(&mut app);
                        }
                    }
                    KeyCode::Char('k') | KeyCode::Up => {
                        if app.selected > 0 {
                            app.selected -= 1;
                            app.update_changed_files();
                            adjust_scroll(&mut app);
                        }
                    }
                    KeyCode::Char('h') | KeyCode::Left => {
                        // select left branch same commit
                        if let Some(ci) = app.commits.get(app.selected) {
                            if ci.branches.len() > 1 {
                                let cur = app.branch_selection.get(&ci.oid).cloned().unwrap_or(0);
                                if cur > 0 {
                                    app.branch_selection.insert(ci.oid, cur - 1);
                                }
                            }
                        }
                    }
                    KeyCode::Char('l') | KeyCode::Right => {
                        if let Some(ci) = app.commits.get(app.selected) {
                            if ci.branches.len() > 1 {
                                let cur = app.branch_selection.get(&ci.oid).cloned().unwrap_or(0);
                                if cur + 1 < ci.branches.len() {
                                    app.branch_selection.insert(ci.oid, cur + 1);
                                }
                            }
                        }
                    }
                    KeyCode::Char('g') | KeyCode::Home => {
                        app.selected = 0;
                        app.update_changed_files();
                        app.scroll_offset = 0;
                    }
                    KeyCode::Char('G') | KeyCode::End => {
                        if !app.commits.is_empty() {
                            app.selected = app.commits.len() - 1;
                            app.update_changed_files();
                            // set scroll to bottom
                            // will be adjusted in draw
                        }
                    }
                    KeyCode::Char('@') => {
                        // jump to HEAD
                        if let Some(oid) = app.head_oid {
                            if let Some(&idx) = app.oid_to_index.get(&oid) {
                                app.selected = idx;
                                app.update_changed_files();
                                adjust_scroll(&mut app);
                            }
                        }
                    }
                    KeyCode::Char(']') | KeyCode::Tab => {
                        // next branch commit
                        let mut next = None;
                        for idx in (app.selected + 1)..app.commits.len() {
                            if !app.commits[idx].branches.is_empty() {
                                next = Some(idx);
                                break;
                            }
                        }
                        if let Some(n) = next {
                            app.selected = n;
                            app.update_changed_files();
                            adjust_scroll(&mut app);
                        }
                    }
                    KeyCode::Char('[') => {
                        let mut prev = None;
                        for idx in (0..app.selected).rev() {
                            if !app.commits[idx].branches.is_empty() {
                                prev = Some(idx);
                                break;
                            }
                        }
                        if let Some(p) = prev {
                            app.selected = p;
                            app.update_changed_files();
                            adjust_scroll(&mut app);
                        }
                    }
                    KeyCode::BackTab => {
                        // Shift+Tab is BackTab
                        let mut prev = None;
                        for idx in (0..app.selected).rev() {
                            if !app.commits[idx].branches.is_empty() {
                                prev = Some(idx);
                                break;
                            }
                        }
                        if let Some(p) = prev {
                            app.selected = p;
                            app.update_changed_files();
                            adjust_scroll(&mut app);
                        }
                    }
                    KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        // page down
                        let page = 10;
                        if app.selected + page < app.commits.len() {
                            app.selected += page;
                        } else {
                            app.selected = app.commits.len() - 1;
                        }
                        app.update_changed_files();
                        adjust_scroll(&mut app);
                    }
                    KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        let page = 10;
                        if app.selected >= page {
                            app.selected -= page;
                        } else {
                            app.selected = 0;
                        }
                        app.update_changed_files();
                        adjust_scroll(&mut app);
                    }
                    KeyCode::Char('b') => {
                        app.create_branch_mode = true;
                        app.create_branch_input.clear();
                    }
                    KeyCode::Char('d') => {
                        // delete branch - only local non-HEAD
                        if let Some(ci) = app.commits.get(app.selected) {
                            if ci.oid == Oid::zero() {
                                continue;
                            }
                            let branch_idx = app.branch_selection.get(&ci.oid).cloned().unwrap_or(0);
                            if let Some(b) = ci.branches.get(branch_idx) {
                                if b.is_remote {
                                    continue;
                                }
                                if b.is_head {
                                    app.error_popup = Some(format!("Cannot delete HEAD branch '{}'", b.name));
                                    continue;
                                }
                                // confirm
                                app.confirm_delete = Some(b.name.clone());
                            }
                        }
                    }
                    KeyCode::Char('f') => {
                        // fetch
                        app.fetching = true;
                        app.status_message = Some(("Fetching from origin...".to_string(), Instant::now()));
                        // do fetch in background? for now synchronous
                        match do_fetch(&app.repo, &mut app) {
                            Ok(_) => {
                                app.status_message = Some(("Fetched from origin".to_string(), Instant::now()));
                                app.status_error = false;
                                let _ = app.refresh();
                            }
                            Err(e) => {
                                app.status_message = Some((format!("git fetch failed: {}", e), Instant::now()));
                                app.status_error = true;
                                app.error_popup = Some(format!("git fetch failed: {}", e));
                            }
                        }
                        app.fetching = false;
                        app.last_fetch = Instant::now();
                    }
                    KeyCode::Char('R') => {
                        let _ = app.refresh();
                        app.status_message = Some(("Refreshed".to_string(), Instant::now()));
                    }
                    KeyCode::Char('/') => {
                        app.search_mode = true;
                        app.search_input.clear();
                        app.search_results.clear();
                        app.search_selected = 0;
                        update_search_results(&mut app);
                    }
                    KeyCode::Enter => {
                        // checkout
                        if let Some(ci) = app.commits.get(app.selected).cloned() {
                            if ci.oid == Oid::zero() {
                                continue;
                            }
                            // If commit has branches, checkout selected branch, else checkout commit
                            let branch_idx = app.branch_selection.get(&ci.oid).cloned().unwrap_or(0);
                            let branch_opt = ci.branches.get(branch_idx);
                            let result = if let Some(b) = branch_opt {
                                checkout_branch(&app.repo, b)
                            } else {
                                checkout_commit(&app.repo, ci.oid)
                            };
                            match result {
                                Ok(_) => {
                                    app.status_message = Some((format!("Checked out {}", branch_opt.map(|b| b.name.as_str()).unwrap_or(&ci.short_hash)), Instant::now()));
                                    let _ = app.refresh();
                                }
                                Err(e) => {
                                    app.error_popup = Some(format!("Checkout failed: {}", e));
                                }
                            }
                        }
                    }
                    _ => {
                        if key.modifiers.contains(KeyModifiers::CONTROL) {
                            match key.code {
                                KeyCode::Char('d') => {
                                    let page = 10;
                                    if app.selected + page < app.commits.len() {
                                        app.selected += page;
                                    } else if !app.commits.is_empty() {
                                        app.selected = app.commits.len() - 1;
                                    }
                                    app.update_changed_files();
                                    adjust_scroll(&mut app);
                                }
                                KeyCode::Char('u') => {
                                    let page = 10;
                                    if app.selected >= page {
                                        app.selected -= page;
                                    } else {
                                        app.selected = 0;
                                    }
                                    app.update_changed_files();
                                    adjust_scroll(&mut app);
                                }
                                _ => {}
                            }
                        }
                    }
                }

                // Also handle Ctrl+d/u via code above, but need to handle actual KeyCode::Char('d') with ctrl already handled; fallback for crossterm might send Char('d') with ctrl modifier
                // The above match for 'b','d','f' etc should not trigger when ctrl is held - we already handled ctrl cases earlier; but to avoid conflict, check modifiers
            }
        }

        // clear status after 3 seconds
        if let Some((_, t)) = &app.status_message {
            if t.elapsed() > Duration::from_secs(3) {
                app.status_message = None;
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen, event::DisableMouseCapture)?;
    terminal.show_cursor()?;
    Ok(())
}

fn adjust_scroll(app: &mut App) {
    // This will be handled in UI draw by ensuring selected visible
}

fn update_search_results(app: &mut App) {
    let input = app.search_input.to_lowercase();
    let mut all_branches: Vec<String> = Vec::new();
    let mut seen = HashSet::new();
    for ci in &app.commits {
        for b in &ci.branches {
            if seen.insert(b.name.clone()) {
                all_branches.push(b.name.clone());
            }
        }
    }
    all_branches.sort();
    if input.is_empty() {
        app.search_results = Vec::new();
    } else {
        // fuzzy: simple contains
        let mut filtered: Vec<String> = all_branches.into_iter().filter(|name| name.to_lowercase().contains(&input)).collect();
        // also sort by fuzzy score? For now simple
        filtered.sort_by(|a,b| a.to_lowercase().find(&input).cmp(&b.to_lowercase().find(&input)));
        app.search_results = filtered;
    }
    app.search_selected = 0;
}

fn create_branch(repo: &Repository, name: &str, oid: Oid) -> Result<()> {
    let commit = repo.find_commit(oid)?;
    repo.branch(name, &commit, false)?;
    Ok(())
}

fn delete_branch(repo: &Repository, name: &str) -> Result<()> {
    let mut branch = repo.find_branch(name, BranchType::Local)?;
    branch.delete()?;
    Ok(())
}

fn checkout_branch(repo: &Repository, branch: &BranchInfo) -> Result<()> {
    if branch.is_remote {
        // remote branch like origin/feature
        // extract local name after slash
        let local_name = branch.name.split('/').last().unwrap_or(&branch.name).to_string();
        // Check if local branch exists
        let local_exists = repo.find_branch(&local_name, BranchType::Local).is_ok();
        // Get remote branch target oid
        let remote_branch = repo.find_branch(&branch.name, BranchType::Remote)?;
        let remote_oid = remote_branch.get().target().context("remote branch has no target")?;
        let remote_commit = repo.find_commit(remote_oid)?;

        if local_exists {
            let mut local_branch = repo.find_branch(&local_name, BranchType::Local)?;
            let local_oid = local_branch.get().target().unwrap();
            if local_oid != remote_oid {
                // force update local branch to remote
                // need to delete and recreate? Use branch set target via reference
                let refname = format!("refs/heads/{}", local_name);
                repo.reference(&refname, remote_oid, true, &format!("update {} to {}", local_name, remote_oid))?;
            }
            // set upstream only if new? Not needed for existing, per docs upstream only when newly created
        } else {
            // create new local branch
            repo.branch(&local_name, &remote_commit, false)?;
            // set upstream
            let mut local_branch = repo.find_branch(&local_name, BranchType::Local)?;
            let remote_name = branch.name.split('/').next().unwrap_or("origin");
            let upstream = format!("{}/{}", remote_name, local_name);
            // try to set upstream, ignore errors
            let _ = local_branch.set_upstream(Some(&branch.name));
        }
        // checkout local branch via git command for simplicity (to update HEAD and working tree)
        let workdir = repo.workdir().unwrap_or(Path::new("."));
        let status = ProcessCommand::new("git").arg("checkout").arg(&local_name).current_dir(workdir).status()?;
        if !status.success() {
            anyhow::bail!("git checkout failed");
        }
    } else {
        // local branch
        let workdir = repo.workdir().unwrap_or(Path::new("."));
        let status = ProcessCommand::new("git").arg("checkout").arg(&branch.name).current_dir(workdir).status()?;
        if !status.success() {
            anyhow::bail!("git checkout failed");
        }
    }
    Ok(())
}

fn checkout_commit(repo: &Repository, oid: Oid) -> Result<()> {
    let workdir = repo.workdir().unwrap_or(Path::new("."));
    let status = ProcessCommand::new("git").arg("checkout").arg(oid.to_string()).current_dir(workdir).status()?;
    if !status.success() {
        anyhow::bail!("git checkout failed");
    }
    Ok(())
}

fn do_fetch(repo: &Repository, app: &mut App) -> Result<()> {
    let workdir = repo.workdir().unwrap_or(Path::new("."));
    // check if origin exists
    if repo.find_remote("origin").is_err() {
        anyhow::bail!("fatal: 'origin' does not appear to be a git repository\nfatal: Could not read from remote repository.\n\nPlease make sure you have the correct access rights\nand the repository exists.");
    }
    let output = ProcessCommand::new("git").arg("fetch").arg("origin").current_dir(workdir).output()?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        anyhow::bail!("{}", stderr);
    }
    Ok(())
}

fn ui(f: &mut ratatui::Frame, app: &mut App) {
    let area = f.area();
    // overall layout: commits on top, details bottom, status bar at bottom 1 height
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(9), Constraint::Length(1)])
        .split(area);

    let commits_area = chunks[0];
    let details_area = chunks[1];
    let status_area = chunks[2];

    // For narrow terminal, details may be stacked vertically
    // If width < 60, split details vertically instead of horizontally
    let details_chunks = if details_area.width < 60 {
        Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
            .split(details_area)
    } else {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
            .split(details_area)
    };

    // Draw commits block
    let commits_block = Block::default().title(" Commits ").borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray));
    let inner_commits = commits_block.inner(commits_area);
    f.render_widget(commits_block, commits_area);

    // Need to compute visible rows
    let height = inner_commits.height as usize;
    if app.commits.is_empty() {
        let para = Paragraph::new("No commits");
        f.render_widget(para, inner_commits);
    } else {
        // Ensure selected is visible
        if app.selected < app.scroll_offset {
            app.scroll_offset = app.selected;
        } else if app.selected >= app.scroll_offset + height {
            app.scroll_offset = app.selected - height + 1;
        }
        // Also handle End/G bottom case
        if app.selected == app.commits.len() - 1 {
            if app.commits.len() > height {
                app.scroll_offset = app.commits.len() - height;
            }
        }

        // For each visible row, render
        let mut items: Vec<ListItem> = Vec::new();
        for idx in app.scroll_offset..std::cmp::min(app.scroll_offset + height, app.commits.len()) {
            let ci = &app.commits[idx];
            let is_selected = idx == app.selected;
            let graph = app.graph_cache.get(idx).cloned().unwrap_or_default();

            // Branch label
            let branch_label = if ci.branches.is_empty() {
                String::new()
            } else {
                let sel_idx = app.branch_selection.get(&ci.oid).cloned().unwrap_or(0);
                let b = &ci.branches[sel_idx];
                let display_name = if ci.branches.len() > 1 {
                    // show +N
                    let others = ci.branches.len() - 1;
                    format!("[{} +{}]", b.name, others)
                } else {
                    format!("[{}]", b.name)
                };
                // For remote tracking like feature ↔ origin, we need to detect if branch has upstream? Our BranchInfo currently just lists branches, but we need to show combined label like [feature ↔ origin]
                // For now, if there are two branches with same oid and one is remote, we could combine. But our current per-oid branches will list both [feature] and [origin/feature] as separate entries, not combined.
                // Original shows "[feature ↔ origin]" when local and remote point to same commit.
                // We need to combine: if a commit has both local and remote branches that correspond (e.g., feature and origin/feature), show as "[feature ↔ origin]"
                // Detect: if branches contains a local and a remote where remote ends with local name
                // For simplicity, if commit has >1 branches and one local + one remote with same suffix, combine.
                // But our current display for single branch will show either [feature] or [origin/feature]. To get "[feature ↔ origin]" we need to detect that case.
                // Let's implement detection: if branches length relates to pairing, produce combined label.
                display_name
            };

            // For combined remote tracking, check if we have both local and remote
            let branch_label = if ci.branches.len() >= 2 {
                // check for local/remote pair
                let mut local = None;
                let mut remote = None;
                for b in &ci.branches {
                    if b.is_remote {
                        remote = Some(b.name.clone());
                    } else {
                        local = Some(b.name.clone());
                    }
                }
                if let (Some(l), Some(r)) = (local, remote) {
                    // check if r ends with l or contains l
                    if r.ends_with(&l) {
                        format!("[{} ↔ origin]", l)
                    } else {
                        // fallback to previous logic
                        let sel_idx = app.branch_selection.get(&ci.oid).cloned().unwrap_or(0);
                        let b = &ci.branches[sel_idx];
                        if ci.branches.len() > 1 {
                            format!("[{} +{}]", b.name, ci.branches.len() - 1)
                        } else {
                            format!("[{}]", b.name)
                        }
                    }
                } else {
                    branch_label
                }
            } else {
                branch_label
            };

