    fn refresh(&mut self) -> Result<()> {
        let workdir = self.repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
        self.repo = Repository::discover(&workdir).unwrap_or_else(|_| Repository::open(&workdir).unwrap());
        self.load_commits()?;
        self.update_head()?;
        self.update_changed_files();
        self.last_refresh = Instant::now();
        if self.selected >= self.commits.len() && !self.commits.is_empty() {
            self.selected = self.commits.len() - 1;
        }
        self.build_graph_cache();
        Ok(())
    }
    fn update_head(&mut self) -> Result<()> {
        self.head_oid = None;
        self.head_branch = None;
        if let Ok(head) = self.repo.head() {
            if let Some(name) = head.shorthand() {
                self.head_branch = Some(name.to_string());
            }
            if let Some(oid) = head.target() {
                self.head_oid = Some(oid);
            } else if let Ok(commit) = head.peel_to_commit() {
                self.head_oid = Some(commit.id());
            }
        } else if let Ok(oid) = self.repo.refname_to_id("HEAD") {
            self.head_oid = Some(oid);
        }
        Ok(())
    }
    fn load_commits(&mut self) -> Result<()> {
        self.commits.clear();
        self.oid_to_index.clear();
        let mut oid_to_branches: HashMap<Oid, Vec<BranchInfo>> = HashMap::new();
        if let Ok(branches) = self.repo.branches(Some(BranchType::Local)) {
            for b in branches {
                if let Ok((branch, _)) = b {
                    if let Ok(Some(name)) = branch.name() {
                        if let Some(oid) = branch.get().target() {
                            oid_to_branches.entry(oid).or_default().push(BranchInfo { name: name.to_string(), is_remote: false, is_head: branch.is_head() });
                        }
                    }
                }
            }
        }
        if let Ok(branches) = self.repo.branches(Some(BranchType::Remote)) {
            for b in branches {
                if let Ok((branch, _)) = b {
                    if let Ok(Some(name)) = branch.name() {
                        if name.ends_with("/HEAD") { continue; }
                        if let Some(oid) = branch.get().target() {
                            oid_to_branches.entry(oid).or_default().push(BranchInfo { name: name.to_string(), is_remote: true, is_head: false });
                        }
                    }
                }
            }
        }
        let mut revwalk = self.repo.revwalk()?;
        revwalk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;
        let _ = revwalk.push_glob("refs/heads/*");
        let _ = revwalk.push_glob("refs/remotes/*");
        if self.repo.head().is_err() {
            if let Ok(oid) = self.repo.refname_to_id("HEAD") { let _ = revwalk.push(oid); }
        }
        let mut commits_vec: Vec<CommitInfo> = Vec::new();
        let mut seen: HashSet<Oid> = HashSet::new();
        for oid_res in revwalk {
            if commits_vec.len() >= MAX_COMMITS { break; }
            let oid = match oid_res { Ok(o) => o, Err(_) => continue };
            if seen.contains(&oid) { continue; }
            seen.insert(oid);
            let commit = match self.repo.find_commit(oid) { Ok(c) => c, Err(_) => continue };
            let message = commit.summary().unwrap_or("").to_string();
            let full_message = commit.message().unwrap_or("").to_string();
            let author = commit.author();
            let author_name = author.name().unwrap_or("").to_string();
            let author_email = author.email().unwrap_or("").to_string();
            let time = commit.time();
            let timestamp = time.seconds();
            let datetime = DateTime::from_timestamp(timestamp, 0).unwrap_or_else(|| DateTime::from_timestamp(0,0).unwrap());
            let local: DateTime<Local> = datetime.with_timezone(&Local);
            let date_short = local.format("%Y-%m-%d").to_string();
            let date_long = local.format("%Y-%m-%d %H:%M:%S").to_string();
            let full_hash = oid.to_string();
            let short_hash = full_hash[..7].to_string();
            let parents: Vec<Oid> = (0..commit.parent_count()).filter_map(|i| commit.parent_id(i).ok()).collect();
            let branches = oid_to_branches.get(&oid).cloned().unwrap_or_default();
            let is_head = self.head_oid.map_or(false, |h| h == oid);
            commits_vec.push(CommitInfo { oid, short_hash, full_hash, message, full_message, author: author_name, author_email, date: date_short, date_time: date_long, timestamp, parents, branches, is_head });
        }
        let has_uncommitted = self.has_uncommitted_changes();
        if has_uncommitted.0 {
            let pseudo = CommitInfo { oid: Oid::zero(), short_hash: "".to_string(), full_hash: "".to_string(), message: format!("uncommitted changes ({})", has_uncommitted.1), full_message: "".to_string(), author: "".to_string(), author_email: "".to_string(), date: "".to_string(), date_time: "".to_string(), timestamp: i64::MAX, parents: Vec::new(), branches: Vec::new(), is_head: false };
            commits_vec.insert(0, pseudo);
        }
        for (idx, c) in commits_vec.iter().enumerate() {
            if c.oid != Oid::zero() { self.oid_to_index.insert(c.oid, idx); }
        }
        self.commits = commits_vec;
        if let Some(head_oid) = self.head_oid {
            if let Some(&idx) = self.oid_to_index.get(&head_oid) { self.selected = idx; }
            else if !self.commits.is_empty() {
                if self.commits[0].oid == Oid::zero() && self.commits.len() > 1 { self.selected = 1; } else { self.selected = 0; }
            }
        } else { self.selected = 0; }
        for c in &self.commits { if !c.branches.is_empty() { self.branch_selection.entry(c.oid).or_insert(0); } }
        Ok(())
    }
    fn has_uncommitted_changes(&self) -> (bool, usize) {
        let mut count = 0;
        let mut has = false;
        if let Ok(statuses) = self.repo.statuses(None) {
            for entry in statuses.iter() {
                let s = entry.status();
                if s.is_wt_new() { continue; }
                if s.is_index_modified() || s.is_index_new() || s.is_index_deleted() || s.is_index_renamed() || s.is_index_typechange() || s.is_wt_modified() || s.is_wt_deleted() || s.is_wt_renamed() || s.is_wt_typechange() { has = true; count += 1; }
            }
        }
        (has, count)
    }
    fn build_graph_cache(&mut self) {
        self.graph_cache.clear();
        if self.commits.is_empty() { return; }
        let mut tracks: Vec<Option<Oid>> = Vec::new();
        let mut commit_cols: Vec<usize> = Vec::new();
        for commit in &self.commits {
            if commit.oid == Oid::zero() { commit_cols.push(0); continue; }
            let mut col = None;
            for (i, track) in tracks.iter().enumerate() { if *track == Some(commit.oid) { col = Some(i); break; } }
            let col_idx = if let Some(c) = col { c } else {
                let mut empty = None;
                for (i, t) in tracks.iter().enumerate() { if t.is_none() { empty = Some(i); break; } }
                if let Some(e) = empty { tracks[e] = Some(commit.oid); e } else { tracks.push(Some(commit.oid)); tracks.len()-1 }
            };
            commit_cols.push(col_idx);
            let mut next_tracks = tracks.clone();
            if !commit.parents.is_empty() {
                let first = commit.parents[0];
                next_tracks[col_idx] = Some(first);
                for parent in commit.parents.iter().skip(1) {
                    let mut found = None;
                    for (i, t) in next_tracks.iter().enumerate() { if *t == Some(*parent) { found = Some(i); break; } }
                    if found.is_none() {
                        let mut empty = None;
                        for (i, t) in next_tracks.iter().enumerate() { if t.is_none() { empty = Some(i); break; } }
                        if let Some(e) = empty { next_tracks[e] = Some(*parent); } else { next_tracks.push(Some(*parent)); }
                    }
                }
            } else {
                if col_idx < next_tracks.len() { next_tracks[col_idx] = None; }
            }
            while next_tracks.last() == Some(&None) { next_tracks.pop(); }
            tracks = next_tracks;
        }
        let max_col = commit_cols.iter().max().cloned().unwrap_or(0) + 2;
        let mut cur_tracks: Vec<Option<Oid>> = Vec::new();
        for (idx, commit) in self.commits.iter().enumerate() {
            let col = commit_cols[idx];
            while cur_tracks.len() <= max_col { cur_tracks.push(None); }
            if commit.oid == Oid::zero() { self.graph_cache.push("●      ".to_string()); continue; }
            let is_selected = idx == self.selected;
            let is_merge = commit.parents.len() > 1;
            let mut row_chars: Vec<String> = Vec::new();
            for c in 0..=max_col {
                if c < col {
                    if cur_tracks[c].is_some() { row_chars.push("│ ".to_string()); } else { row_chars.push("  ".to_string()); }
                } else if c == col {
                    if is_selected {
                        if is_merge && cur_tracks.iter().skip(col+1).any(|x| x.is_some()) { row_chars.push("◉─╮".to_string()); } else { row_chars.push("◉ ".to_string()); }
                    } else {
                        if is_merge && cur_tracks.iter().skip(col+1).any(|x| x.is_some()) { row_chars.push("●─╮".to_string()); } else { row_chars.push("● ".to_string()); }
                    }
                } else {
                    if cur_tracks[c].is_some() { row_chars.push("│ ".to_string()); } else { row_chars.push("  ".to_string()); }
                }
            }
            let joined = row_chars.concat();
            let graph_str = joined.chars().take(10).collect::<String>();
            self.graph_cache.push(graph_str);
            let mut next = cur_tracks.clone();
            while next.len() <= max_col { next.push(None); }
            if !commit.parents.is_empty() {
                let first = commit.parents[0];
                if col < next.len() { next[col] = Some(first); }
                for parent in commit.parents.iter().skip(1) {
                    let mut found = None;
                    for (i, t) in next.iter().enumerate() { if *t == Some(*parent) { found = Some(i); break; } }
                    if found.is_none() {
                        let mut empty = None;
                        for (i, t) in next.iter().enumerate() { if t.is_none() { empty = Some(i); break; } }
                        if let Some(e) = empty { next[e] = Some(*parent); } else { next.push(Some(*parent)); }
                    }
                }
            } else {
                if col < next.len() { next[col] = None; }
            }
            while next.last() == Some(&None) { next.pop(); }
            cur_tracks = next;
        }
        while self.graph_cache.len() < self.commits.len() { self.graph_cache.push("".to_string()); }
    }
    fn update_changed_files(&mut self) {
        self.changed_files.clear();
        self.changed_files_total.clear();
        self.changed_files_loading = true;
        if self.commits.is_empty() || self.selected >= self.commits.len() { self.changed_files_loading = false; return; }
        let ci = &self.commits[self.selected];
        if ci.oid == Oid::zero() {
            let mut files = Vec::new();
            let mut add = 0; let mut del = 0;
            if let Ok(statuses) = self.repo.statuses(None) {
                for entry in statuses.iter() {
                    let s = entry.status();
                    if s.is_wt_new() { continue; }
                    let path = entry.path().unwrap_or("").to_string();
                    let status_char = if s.is_wt_modified() || s.is_index_modified() { 'M' } else if s.is_wt_deleted() || s.is_index_deleted() { 'D' } else { 'M' };
                    files.push(ChangedFile { path, status: status_char, additions: 1, deletions: 1 });
                    add += 1; del += 1;
                    if files.len() >= 50 { break; }
                }
            }
            self.changed_files = files;
            self.changed_files_total = format!("{} files changed  +{} -{}", self.changed_files.len(), add, del);
            self.changed_files_loading = false;
            return;
        }
        let oid = ci.oid;
        let commit = match self.repo.find_commit(oid) { Ok(c) => c, Err(_) => { self.changed_files_loading = false; return; } };
        let diff = if commit.parent_count() == 0 {
            let tree = commit.tree().ok();
            self.repo.diff_tree_to_tree(None, tree.as_ref(), None).ok()
        } else if commit.parent_count() > 1 {
            let parent = commit.parent(0).ok();
            let parent_tree = parent.as_ref().and_then(|p| p.tree().ok());
            let tree = commit.tree().ok();
            self.repo.diff_tree_to_tree(parent_tree.as_ref(), tree.as_ref(), None).ok()
        } else {
            let parent = commit.parent(0).ok();
            let parent_tree = parent.as_ref().and_then(|p| p.tree().ok());
            let tree = commit.tree().ok();
            self.repo.diff_tree_to_tree(parent_tree.as_ref(), tree.as_ref(), None).ok()
        };
        if let Some(mut diff) = diff {
            let mut files = Vec::new();
            let mut total_add = 0; let mut total_del = 0;
            if let Ok(s) = diff.stats() {
                total_add = s.insertions(); total_del = s.deletions();
                let cnt = s.files_changed();
                self.changed_files_total = format!("{} files changed  +{} -{}", cnt, total_add, total_del);
            } else { self.changed_files_total = "0 files changed  +0 -0".to_string(); }
            let _ = diff.foreach(&mut |delta, _| {
                if files.len() >= 50 { return false; }
                let path = delta.new_file().path().or_else(|| delta.old_file().path()).map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
                let status = match delta.status() { git2::Delta::Added => 'A', git2::Delta::Deleted => 'D', git2::Delta::Modified => 'M', git2::Delta::Renamed => 'R', _ => 'M' };
                files.push(ChangedFile { path, status, additions: 0, deletions: 0 });
                true
            }, None, None, None);
            if self.changed_files_total.is_empty() { self.changed_files_total = format!("{} files changed  +{} -{}", files.len(), total_add, total_del); }
            self.changed_files = files;
        } else { self.changed_files_total = "0 files changed  +0 -0".to_string(); }
        self.changed_files_loading = false;
    }
}
