use std::process::Command as ProcessCommand;
use std::time::{Duration, Instant};
mod config;
use config::AppConfig;
const VERSION: &str = "0.2.3";
const MAX_COMMITS: usize = 500;
#[derive(Debug, Clone)]
struct CommitInfo {
    oid: Oid,
    short_hash: String,
    full_hash: String,
    message: String,
    full_message: String,
    author: String,
    author_email: String,
    date: String,
    date_time: String,
