            std::process::exit(1);
        }
    };
    if let Err(e) = run_app(repo) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}
struct App {
    repo: Repository,
    commits: Vec<CommitInfo>,
    oid_to_idx: HashMap<Oid, usize>,
    selected: usize,
    branch_sel: HashMap<Oid, usize>,
    head_oid: Option<Oid>,
    head_branch: Option<String>,
    repo_name: String,
    config: AppConfig,
    show_help: bool,
    search_mode: bool,
    search_input: String,
    search_results: Vec<String>,
    search_sel: usize,
    create_mode: bool,
    create_input: String,
    confirm_del: Option<String>,
    error_popup: Option<String>,
    status_msg: Option<(String, Instant)>,
    status_err: bool,
    scroll: usize,
    graph: Vec<String>,
    changed: Vec<ChangedFile>,
    changed_total: String,
    last_refresh: Instant,
    last_fetch: Instant,
}
impl App {
    fn new(repo: Repository) -> anyhow::Result<Self> {
        let workdir = repo.workdir().unwrap_or_else(|| Path::new(".")).to_path_buf();
        let repo_name = workdir.file_name().and_then(|s| s.to_str()).unwrap_or("repo").to_string();
        let config = config::load();
        let mut a = Self {
            repo, commits: Vec::new(), oid_to_idx: HashMap::new(), selected: 0, branch_sel: HashMap::new(),
            head_oid: None, head_branch: None, repo_name, config, show_help: false,
            search_mode: false, search_input: String::new(), search_results: Vec::new(), search_sel: 0,
            create_mode: false, create_input: String::new(), confirm_del: None, error_popup: None,
            status_msg: None, status_err: false, scroll: 0, graph: Vec::new(), changed: Vec::new(),
            changed_total: String::new(), last_refresh: Instant::now(), last_fetch: Instant::now(),
        };
        a.refresh()?;
        Ok(a)
    }
    fn refresh(&mut self) -> anyhow::Result<()> {
        let wd = self.repo.workdir().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));
        self.repo = Repository::discover(&wd).unwrap_or_else(|_| Repository::open(&wd).unwrap());
        self.load_commits()?;
        self.update_head()?;
        self.update_changed();
        self.last_refresh = Instant::now();
        if self.selected >= self.commits.len() && !self.commits.is_empty() { self.selected = self.commits.len()-1; }
        self.build_graph();
        Ok(())
    }
    fn update_head(&mut self) -> anyhow::Result<()> {
        self.head_oid = None;
        self.head_branch = None;
        if let Ok(head) = self.repo.head() {
            if let Some(n) = head.shorthand() { self.head_branch = Some(n.to_string()); }
            if let Some(oid) = head.target() { self.head_oid = Some(oid); }
            else if let Ok(c) = head.peel_to_commit() { self.head_oid = Some(c.id()); }
        } else if let Ok(oid) = self.repo.refname_to_id("HEAD") { self.head_oid = Some(oid); }
        Ok(())
    }
    fn load_commits(&mut self) -> anyhow::Result<()> {
        self.commits.clear(); self.oid_to_idx.clear();
        let mut map: HashMap<Oid, Vec<BranchInfo>> = HashMap::new();
        if let Ok(br) = self.repo.branches(Some(BranchType::Local)) {
            for b in br { if let Ok((br,_)) = b { if let Ok(Some(n)) = br.name() { if let Some(oid) = br.get().target() { map.entry(oid).or_default().push(BranchInfo{name:n.to_string(), is_remote:false, is_head:br.is_head()}); } } } }
        }
        if let Ok(br) = self.repo.branches(Some(BranchType::Remote)) {
            for b in br { if let Ok((br,_)) = b { if let Ok(Some(n)) = br.name() { if n.ends_with("/HEAD") { continue; } if let Some(oid)=br.get().target(){ map.entry(oid).or_default().push(BranchInfo{name:n.to_string(), is_remote:true, is_head:false}); } } } }
        }
        let mut walk = self.repo.revwalk()?;
        walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;
        let _ = walk.push_glob("refs/heads/*");
        let _ = walk.push_glob("refs/remotes/*");
        if self.repo.head().is_err() { if let Ok(oid)=self.repo.refname_to_id("HEAD") { let _=walk.push(oid); } }
        let mut vec: Vec<CommitInfo> = Vec::new();
        let mut seen=HashSet::new();
        for r in walk {
            if vec.len() >= MAX_COMMITS {break;}
            let oid = match r {Ok(o)=>o, Err(_)=>continue};
            if seen.contains(&oid) {continue;}
            seen.insert(oid);
            let c = match self.repo.find_commit(oid){Ok(c)=>c,Err(_)=>continue};
            let msg = c.summary().unwrap_or("").to_string();
            let full = c.message().unwrap_or("").to_string();
            let author = c.author();
            let an = author.name().unwrap_or("").to_string();
            let ae = author.email().unwrap_or("").to_string();
            let ts = c.time().seconds();
            let dt = DateTime::from_timestamp(ts,0).unwrap_or_else(|| DateTime::from_timestamp(0,0).unwrap());
            let local: DateTime<Local> = dt.with_timezone(&Local);
            let ds = local.format("%Y-%m-%d").to_string();
            let dl = local.format("%Y-%m-%d %H:%M:%S").to_string();
            let fh = oid.to_string();
            let sh = fh[..7].to_string();
            let parents: Vec<Oid> = (0..c.parent_count()).filter_map(|i| c.parent_id(i).ok()).collect();
            let branches = map.get(&oid).cloned().unwrap_or_default();
            vec.push(CommitInfo{oid, short_hash:sh, full_hash:fh, message:msg, full_message:full, author:an, author_email:ae, date:ds, date_time:dl, parents, branches});
        }
        let (has,cnt) = self.has_uncommitted();
        if has {
            vec.insert(0, CommitInfo{oid:Oid::zero(), short_hash:"".into(), full_hash:"".into(), message:format!("uncommitted changes ({})",cnt), full_message:"".into(), author:"".into(), author_email:"".into(), date:"".into(), date_time:"".into(), parents:Vec::new(), branches:Vec::new()});
        }
        for (i,c) in vec.iter().enumerate() { if c.oid!=Oid::zero() {self.oid_to_idx.insert(c.oid,i);} }
        self.commits = vec;
        if let Some(oid)=self.head_oid { if let Some(&idx)=self.oid_to_idx.get(&oid){self.selected=idx;} else if !self.commits.is_empty(){ if self.commits[0].oid==Oid::zero() && self.commits.len()>1 {self.selected=1;} else {self.selected=0;}} } else {self.selected=0;}
        for c in &self.commits { if !c.branches.is_empty(){ self.branch_sel.entry(c.oid).or_insert(0); } }
        Ok(())
    }
    fn has_uncommitted(&self)->(bool,usize){
        let mut c=0; let mut has=false;
        if let Ok(st)=self.repo.statuses(None){
            for e in st.iter(){ let s=e.status(); if s.is_wt_new(){continue;} if s.is_index_modified()||s.is_index_new()||s.is_index_deleted()||s.is_wt_modified()||s.is_wt_deleted(){has=true;c+=1;}}
        }
        (has,c)
    }
    fn build_graph(&mut self){
        self.graph.clear();
        if self.commits.is_empty(){return;}
        let mut tracks: Vec<Option<Oid>> = Vec::new();
        let mut cols: Vec<usize> = Vec::new();
        for commit in &self.commits {
            if commit.oid==Oid::zero(){ cols.push(0); continue;}
            let mut col=None;
            for (i,t) in tracks.iter().enumerate(){ if *t==Some(commit.oid){col=Some(i);break;}}
            let idx = if let Some(c)=col{c} else {
                let mut empty=None;
                for (i,t) in tracks.iter().enumerate(){ if t.is_none(){empty=Some(i);break;}}
                if let Some(e)=empty{tracks[e]=Some(commit.oid);e}else{tracks.push(Some(commit.oid));tracks.len()-1}
            };
            cols.push(idx);
            let mut nxt=tracks.clone();
            if !commit.parents.is_empty(){
                nxt[idx]=Some(commit.parents[0]);
                for p in commit.parents.iter().skip(1){
                    let mut found=None;
                    for (i,t) in nxt.iter().enumerate(){ if *t==Some(*p){found=Some(i);break;}}
                    if found.is_none(){
                        let mut empty=None;
                        for (i,t) in nxt.iter().enumerate(){ if t.is_none(){empty=Some(i);break;}}
                        if let Some(e)=empty{nxt[e]=Some(*p);}else{nxt.push(Some(*p));}
                    }
                }
            } else { if idx < nxt.len(){nxt[idx]=None;}}
            while nxt.last()==Some(&None){nxt.pop();}
            tracks=nxt;
        }
        let max_col = cols.iter().max().cloned().unwrap_or(0)+2;
        let mut cur: Vec<Option<Oid>> = Vec::new();
        for (idx, commit) in self.commits.iter().enumerate(){
            let col=cols[idx];
            while cur.len()<=max_col{cur.push(None);}
            if commit.oid==Oid::zero(){ self.graph.push("●      ".to_string()); continue; }
            let is_sel = idx==self.selected;
            let is_merge = commit.parents.len()>1;
            let mut row: Vec<String>=Vec::new();
            for c in 0..=max_col{
                if c < col{
                    if cur[c].is_some(){row.push("│ ".to_string());}else{row.push("  ".to_string());}
                } else if c==col{
                    if is_sel{
                        if is_merge && cur.iter().skip(col+1).any(|x| x.is_some()){row.push("◉─╮".to_string());}else{row.push("◉ ".to_string());}
                    } else {
                        if is_merge && cur.iter().skip(col+1).any(|x| x.is_some()){row.push("●─╮".to_string());}else{row.push("● ".to_string());}
                    }
                } else {
                    if cur[c].is_some(){row.push("│ ".to_string());}else{row.push("  ".to_string());}
                }
            }
            let joined=row.concat();
            self.graph.push(joined.chars().take(10).collect());
            let mut nxt=cur.clone();
            while nxt.len()<=max_col{nxt.push(None);}
            if !commit.parents.is_empty(){
                nxt[col]=Some(commit.parents[0]);
                for p in commit.parents.iter().skip(1){
                    let mut found=None;
                    for (i,t) in nxt.iter().enumerate(){ if *t==Some(*p){found=Some(i);break;}}
                    if found.is_none(){
                        let mut empty=None;
                        for (i,t) in nxt.iter().enumerate(){ if t.is_none(){empty=Some(i);break;}}
                        if let Some(e)=empty{nxt[e]=Some(*p);}else{nxt.push(Some(*p));}
                    }
                }
            } else { if col < nxt.len(){nxt[col]=None;}}
            while nxt.last()==Some(&None){nxt.pop();}
            cur=nxt;
        }
        while self.graph.len() < self.commits.len(){ self.graph.push("".into());}
    }
    fn update_changed(&mut self){
        self.changed.clear(); self.changed_total.clear();
        if self.commits.is_empty()||self.selected>=self.commits.len(){return;}
        let ci=&self.commits[self.selected];
        if ci.oid==Oid::zero(){
            let mut files=Vec::new();
            if let Ok(st)=self.repo.statuses(None){
                for e in st.iter(){
                    let s=e.status();
                    if s.is_wt_new(){continue;}
                    let path=e.path().unwrap_or("").to_string();
                    let sc = if s.is_wt_modified()||s.is_index_modified(){'M'}else if s.is_wt_deleted()||s.is_index_deleted(){'D'}else{'M'};
                    files.push(ChangedFile{path, status:sc});
                    if files.len()>=50{break;}
                }
            }
            let n=files.len();
            self.changed_total=format!("{} files changed  +{} -{}", n, n, n);
            self.changed=files;
            return;
        }
        let commit = match self.repo.find_commit(ci.oid){Ok(c)=>c,Err(_)=>{self.changed_total="0 files changed  +0 -0".into();return;}};
        let diff = if commit.parent_count()==0{
            self.repo.diff_tree_to_tree(None, commit.tree().ok().as_ref(), None).ok()
        } else if commit.parent_count()>1{
            let parent=commit.parent(0).ok();
            let pt=parent.as_ref().and_then(|p| p.tree().ok());
            self.repo.diff_tree_to_tree(pt.as_ref(), commit.tree().ok().as_ref(), None).ok()
        } else {
            let parent=commit.parent(0).ok();
            let pt=parent.as_ref().and_then(|p| p.tree().ok());
            self.repo.diff_tree_to_tree(pt.as_ref(), commit.tree().ok().as_ref(), None).ok()
        };
        if let Some(mut diff)=diff{
            let mut files=Vec::new();
            let mut add=0; let mut del=0;
            if let Ok(s)=diff.stats(){ add=s.insertions(); del=s.deletions(); let cnt=s.files_changed(); self.changed_total=format!("{} files changed  +{} -{}", cnt, add, del);} else {self.changed_total="0 files changed  +0 -0".into();}
            let _=diff.foreach(&mut |d,_|{
                if files.len()>=50{return false;}
                let path=d.new_file().path().or_else(|| d.old_file().path()).map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
                let st=match d.status(){git2::Delta::Added=>'A',git2::Delta::Deleted=>'D',git2::Delta::Renamed=>'R',_=>'M'};
                files.push(ChangedFile{path, status:st});
                true
            },None,None,None);
            if self.changed_total.is_empty(){self.changed_total=format!("{} files changed  +{} -{}", files.len(), add, del);}
            self.changed=files;
        } else {self.changed_total="0 files changed  +0 -0".into();}
    }
}
fn run_app(repo: Repository) -> anyhow::Result<()>{
    enable_raw_mode().context("No such device or address (os error 6)")?;
    let mut stdout=io::stdout();
    execute!(stdout, EnterAlternateScreen, event::EnableMouseCapture)?;
    let backend=CrosstermBackend::new(stdout);
    let mut term=Terminal::new(backend)?;
    let mut app=App::new(repo)?;
    loop{
        term.draw(|f| ui(f,&mut app))?;
        let now=Instant::now();
        if app.config.auto_refresh && now.duration_since(app.last_refresh) >= Duration::from_secs(app.config.refresh_interval){ let _=app.refresh(); }
        if app.config.auto_fetch && now.duration_since(app.last_fetch) >= Duration::from_secs(app.config.fetch_interval){ let _=do_fetch(&app.repo, &mut app); app.last_fetch=Instant::now(); }
        if event::poll(Duration::from_millis(200))?{
            if let Event::Key(k)=event::read()?{
                if app.error_popup.is_some(){
                    if k.code==KeyCode::Esc || k.code==KeyCode::Enter{ app.error_popup=None; }
                    continue;
                }
                if let Some(_) = app.confirm_del.clone(){
                    match k.code{
                        KeyCode::Char('y')|KeyCode::Char('Y')=>{
                            let br=app.confirm_del.take().unwrap();
                            match delete_branch(&app.repo, &br){
                                Ok(_)=>{app.status_msg=Some((format!("Deleted branch '{}'", br), Instant::now())); app.status_err=false; let _=app.refresh();}
                                Err(e)=>{app.error_popup=Some(format!("Failed to delete branch '{}': {}", br, e));}
                            }
                        },
                        KeyCode::Char('n')|KeyCode::Char('N')|KeyCode::Esc=>{app.confirm_del=None;},
                        _=>{}
                    }
                    continue;
                }
                if app.create_mode{
                    match k.code{
                        KeyCode::Esc=>{app.create_mode=false; app.create_input.clear();}
                        KeyCode::Enter=>{
                            let name=app.create_input.trim().to_string();
                            if !name.is_empty(){
                                if let Some(ci)=app.commits.get(app.selected).cloned(){
                                    if ci.oid!=Oid::zero(){
                                        match create_branch(&app.repo, &name, ci.oid){
                                            Ok(_)=>{app.status_msg=Some((format!("Created branch '{}'", name), Instant::now())); let _=app.refresh();}
                                            Err(_)=>{app.error_popup=Some(format!("Failed to create branch '{}'", name));}
                                        }
                                    }
                                }
                            }
                            app.create_mode=false; app.create_input.clear();
                        },
                        KeyCode::Backspace=>{app.create_input.pop();},
                        KeyCode::Char(c)=>{app.create_input.push(c);},
                        _=>{}
                    }
                    continue;
                }
                if app.search_mode{
                    match k.code{
                        KeyCode::Esc=>{app.search_mode=false; app.search_input.clear(); app.search_results.clear();}
                        KeyCode::Enter=>{
                            if !app.search_results.is_empty(){
                                let sel=app.search_results[app.search_sel].clone();
                                let mut found=None;
                                for (idx,ci) in app.commits.iter().enumerate(){
                                    for b in &ci.branches{ if b.name==sel{found=Some(idx);break;}}
                                    if found.is_some(){break;}
                                }
                                if let Some(idx)=found{
                                    app.selected=idx;
                                    if let Some(ci)=app.commits.get(idx){
                                        for (bi,b) in ci.branches.iter().enumerate(){ if b.name==sel{app.branch_sel.insert(ci.oid,bi);break;}}
                                    }
                                    app.update_changed();
                                }
                            }
                            app.search_mode=false; app.search_input.clear(); app.search_results.clear();
                        },
                        KeyCode::Backspace=>{
                            if app.search_input.is_empty(){app.search_mode=false;} else {app.search_input.pop(); update_search(&mut app);}
                        },
                        KeyCode::Up|KeyCode::BackTab=>{
                            if !app.search_results.is_empty(){
                                if app.search_sel==0{app.search_sel=app.search_results.len()-1;} else {app.search_sel-=1;}
                            }
                        },
                        KeyCode::Down|KeyCode::Tab=>{
                            if !app.search_results.is_empty(){app.search_sel=(app.search_sel+1)%app.search_results.len();}
                        },
                        KeyCode::Char(c)=>{
                            if k.modifiers.contains(KeyModifiers::CONTROL){
                                if c=='k'{
                                    if !app.search_results.is_empty(){ if app.search_sel==0{app.search_sel=app.search_results.len()-1;} else {app.search_sel-=1;}}
                                    continue;
                                } else if c=='j'{
                                    if !app.search_results.is_empty(){app.search_sel=(app.search_sel+1)%app.search_results.len();}
                                    continue;
                                }
                            }
                            app.search_input.push(c); update_search(&mut app);
                        },
                        _=>{
                            if k.modifiers.contains(KeyModifiers::CONTROL){
                                if k.code==KeyCode::Char('k'){ if !app.search_results.is_empty(){ if app.search_sel==0{app.search_sel=app.search_results.len()-1;} else {app.search_sel-=1;}}}
                                else if k.code==KeyCode::Char('j'){ if !app.search_results.is_empty(){app.search_sel=(app.search_sel+1)%app.search_results.len();}}
                            }
                        }
                    }
                    continue;
                }
                if app.show_help{
                    if k.code==KeyCode::Char('?')||k.code==KeyCode::Char('q')||k.code==KeyCode::Esc{app.show_help=false;}
                    continue;
                }
                match k.code{
                    KeyCode::Char('q')|KeyCode::Esc=>break,
                    KeyCode::Char('?')=>app.show_help=true,
                    KeyCode::Char('j')|KeyCode::Down=>{ if app.selected+1 < app.commits.len(){app.selected+=1; app.update_changed();}},
                    KeyCode::Char('k')|KeyCode::Up=>{ if app.selected>0{app.selected-=1; app.update_changed();}},
                    KeyCode::Char('h')|KeyCode::Left=>{
                        if let Some(ci)=app.commits.get(app.selected){ if ci.branches.len()>1{ let cur=app.branch_sel.get(&ci.oid).cloned().unwrap_or(0); if cur>0{app.branch_sel.insert(ci.oid, cur-1);} } }
                    },
                    KeyCode::Char('l')|KeyCode::Right=>{
                        if let Some(ci)=app.commits.get(app.selected){ if ci.branches.len()>1{ let cur=app.branch_sel.get(&ci.oid).cloned().unwrap_or(0); if cur+1 < ci.branches.len(){app.branch_sel.insert(ci.oid, cur+1);} } }
                    },
                    KeyCode::Char('g')|KeyCode::Home=>{app.selected=0; app.update_changed(); app.scroll=0;},
                    KeyCode::Char('G')|KeyCode::End=>{ if !app.commits.is_empty(){app.selected=app.commits.len()-1; app.update_changed();}},
                    KeyCode::Char('@')=>{
                        if let Some(oid)=app.head_oid{ if let Some(&idx)=app.oid_to_idx.get(&oid){app.selected=idx; app.update_changed();}}
                    },
                    KeyCode::Char(']')|KeyCode::Tab=>{
                        let mut nxt=None;
                        for idx in (app.selected+1)..app.commits.len(){ if !app.commits[idx].branches.is_empty(){nxt=Some(idx);break;}}
                        if let Some(n)=nxt{app.selected=n; app.update_changed();}
                    },
                    KeyCode::Char('[')=>{
                        let mut prv=None;
                        for idx in (0..app.selected).rev(){ if !app.commits[idx].branches.is_empty(){prv=Some(idx);break;}}
                        if let Some(p)=prv{app.selected=p; app.update_changed();}
                    },
                    KeyCode::BackTab=>{
                        let mut prv=None;
                        for idx in (0..app.selected).rev(){ if !app.commits[idx].branches.is_empty(){prv=Some(idx);break;}}
                        if let Some(p)=prv{app.selected=p; app.update_changed();}
                    },
                    KeyCode::Char('b')=>{app.create_mode=true; app.create_input.clear();},
                    KeyCode::Char('d') if k.modifiers.contains(KeyModifiers::CONTROL)=>{
                        let page=10;
                        if app.selected+page < app.commits.len(){app.selected+=page;} else {app.selected=app.commits.len()-1;}
                        app.update_changed();
                    },
                    KeyCode::Char('u') if k.modifiers.contains(KeyModifiers::CONTROL)=>{
                        let page=10;
                        if app.selected>=page{app.selected-=page;} else {app.selected=0;}
                        app.update_changed();
                    },
                    KeyCode::Char('d')=>{
                        if let Some(ci)=app.commits.get(app.selected){
                            if ci.oid==Oid::zero(){continue;}
                            let idx=app.branch_sel.get(&ci.oid).cloned().unwrap_or(0);
                            if let Some(b)=ci.branches.get(idx){
                                if b.is_remote{continue;}
                                if b.is_head{app.error_popup=Some(format!("Cannot delete HEAD branch '{}'", b.name));continue;}
                                app.confirm_del=Some(b.name.clone());
                            }
                        }
                    },
                    KeyCode::Char('f')=>{
                        app.status_msg=Some(("Fetching from origin...".into(), Instant::now()));
                        match do_fetch(&app.repo, &mut app){
                            Ok(_)=>{app.status_msg=Some(("Fetched from origin".into(), Instant::now())); app.status_err=false; let _=app.refresh();}
                            Err(e)=>{app.status_msg=Some((format!("git fetch failed: {}", e), Instant::now())); app.status_err=true; app.error_popup=Some(format!("git fetch failed: {}", e));}
                        }
                        app.last_fetch=Instant::now();
                    },
                    KeyCode::Char('R')=>{let _=app.refresh(); app.status_msg=Some(("Refreshed".into(), Instant::now()));},
                    KeyCode::Char('/')=>{app.search_mode=true; app.search_input.clear(); app.search_results.clear(); app.search_sel=0; update_search(&mut app);},
                    KeyCode::Enter=>{
                        if let Some(ci)=app.commits.get(app.selected).cloned(){
                            if ci.oid==Oid::zero(){continue;}
                            let idx=app.branch_sel.get(&ci.oid).cloned().unwrap_or(0);
                            let b=ci.branches.get(idx);
                            let res=if let Some(br)=b{ checkout_branch(&app.repo, br)}else{ checkout_commit(&app.repo, ci.oid)};
                            match res{
                                Ok(_)=>{app.status_msg=Some((format!("Checked out {}", b.map(|x| x.name.as_str()).unwrap_or(&ci.short_hash)), Instant::now())); let _=app.refresh();}
                                Err(e)=>{app.error_popup=Some(format!("Checkout failed: {}", e));}
                            }
                        }
                    },
                    _=>{
                        if k.modifiers.contains(KeyModifiers::CONTROL){
                            match k.code{
                                KeyCode::Char('d')=>{
                                    let page=10;
                                    if app.selected+page < app.commits.len(){app.selected+=page;} else {app.selected=app.commits.len()-1;}
                                    app.update_changed();
                                },
                                KeyCode::Char('u')=>{
                                    let page=10;
                                    if app.selected>=page{app.selected-=page;} else {app.selected=0;}
                                    app.update_changed();
                                },
                                _=>{}
                            }
                        }
                    }
                }
            }
        }
        if let Some((_,t))=&app.status_msg{ if t.elapsed()>Duration::from_secs(3){app.status_msg=None;}}
    }
    disable_raw_mode()?;
    execute!(term.backend_mut(), LeaveAlternateScreen, event::DisableMouseCapture)?;
    term.show_cursor()?;
    Ok(())
}
fn update_search(app: &mut App){
    let inp=app.search_input.to_lowercase();
    let mut all: Vec<String>=Vec::new();
    let mut seen=HashSet::new();
    for ci in &app.commits{ for b in &ci.branches{ if seen.insert(b.name.clone()){all.push(b.name.clone());}}}
    all.sort();
    if inp.is_empty(){app.search_results.clear();} else {
        let mut f: Vec<String>=all.into_iter().filter(|n| n.to_lowercase().contains(&inp)).collect();
        f.sort_by(|a,b| a.to_lowercase().find(&inp).cmp(&b.to_lowercase().find(&inp)));
        app.search_results=f;
    }
    app.search_sel=0;
}
fn create_branch(repo: &Repository, name: &str, oid: Oid)->anyhow::Result<()>{
    let c=repo.find_commit(oid)?; repo.branch(name,&c,false)?; Ok(())
}
fn delete_branch(repo: &Repository, name: &str)->anyhow::Result<()>{
    let mut b=repo.find_branch(name, BranchType::Local)?; b.delete()?; Ok(())
}
fn checkout_branch(repo: &Repository, branch: &BranchInfo)->anyhow::Result<()>{
    if branch.is_remote{
        let local = branch.name.split('/').last().unwrap_or(&branch.name).to_string();
        let exists = repo.find_branch(&local, BranchType::Local).is_ok();
        let remote = repo.find_branch(&branch.name, BranchType::Remote)?;
        let oid = remote.get().target().context("no target")?;
        let commit = repo.find_commit(oid)?;
        if exists{
            let oid_local = repo.find_branch(&local, BranchType::Local)?.get().target().unwrap();
            if oid_local != oid{
                let rname = format!("refs/heads/{}", local);
                repo.reference(&rname, oid, true, &format!("update {}", local))?;
            }
        } else {
            repo.branch(&local, &commit, false)?;
            if let Ok(mut b)=repo.find_branch(&local, BranchType::Local){ let _=b.set_upstream(Some(&branch.name));}
        }
        let wd=repo.workdir().unwrap_or(Path::new("."));
        let st=ProcessCommand::new("git").arg("checkout").arg(&local).current_dir(wd).status()?;
        if !st.success(){ anyhow::bail!("git checkout failed"); }
    } else {
        let wd=repo.workdir().unwrap_or(Path::new("."));
        let st=ProcessCommand::new("git").arg("checkout").arg(&branch.name).current_dir(wd).status()?;
        if !st.success(){ anyhow::bail!("git checkout failed");}
    }
    Ok(())
}
fn checkout_commit(repo: &Repository, oid: Oid)->anyhow::Result<()>{
    let wd=repo.workdir().unwrap_or(Path::new("."));
    let st=ProcessCommand::new("git").arg("checkout").arg(oid.to_string()).current_dir(wd).status()?;
    if !st.success(){anyhow::bail!("git checkout failed");}
    Ok(())
}
fn do_fetch(repo: &Repository, _app: &mut App)->anyhow::Result<()>{
    if repo.find_remote("origin").is_err(){ anyhow::bail!("fatal: 'origin' does not appear to be a git repository\\nfatal: Could not read from remote repository.\\n\\nPlease make sure you have the correct access rights\\nand the repository exists.");}
    let wd=repo.workdir().unwrap_or(Path::new("."));
    let out=ProcessCommand::new("git").arg("fetch").arg("origin").current_dir(wd).output()?;
    if !out.status.success(){ let e=String::from_utf8_lossy(&out.stderr).to_string(); anyhow::bail!("{}", e);}
    Ok(())
}
fn ui(f: &mut ratatui::Frame, app: &mut App){
    let area=f.area();
    let chunks=Layout::default().direction(Direction::Vertical).constraints([Constraint::Min(0), Constraint::Length(9), Constraint::Length(1)]).split(area);
    let commits_area=chunks[0];
    let details_area=chunks[1];
    let status_area=chunks[2];
    let details_chunks = if details_area.width < 60 {
        Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(details_area)
    } else {
        Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(details_area)
    };
    let commits_block=Block::default().title(" Commits ").borders(Borders::ALL).border_style(Style::default().fg(Color::DarkGray));
    let inner=commits_block.inner(commits_area);
    f.render_widget(commits_block, commits_area);
    let h=inner.height as usize;
    if app.commits.is_empty(){
        f.render_widget(Paragraph::new("No commits"), inner);
    } else {
        if app.selected < app.scroll{ app.scroll = app.selected; } else if app.selected >= app.scroll + h { app.scroll = app.selected - h + 1; }
        if app.selected == app.commits.len()-1 && app.commits.len() > h { app.scroll = app.commits.len() - h; }
        let mut items: Vec<ListItem> = Vec::new();
        for idx in app.scroll..std::cmp::min(app.scroll+h, app.commits.len()){
            let ci=&app.commits[idx];
            let is_sel = idx==app.selected;
            let graph = app.graph.get(idx).cloned().unwrap_or_default();
            let branch_label = if ci.branches.is_empty(){String::new()} else {
                let sel = app.branch_sel.get(&ci.oid).cloned().unwrap_or(0);
                let b=&ci.branches[sel];
                if ci.branches.len()>1{format!("[{} +{}]", b.name, ci.branches.len()-1)} else {format!("[{}]", b.name)}
            };
            let branch_label = if ci.branches.len()>=2{
                let mut local=None; let mut remote=None;
                for b in &ci.branches{ if b.is_remote{remote=Some(b.name.clone());} else {local=Some(b.name.clone());}}
                if let (Some(l), Some(r))=(local, remote){ if r.ends_with(&l){format!("[{} ↔ origin]", l)} else {branch_label}} else {branch_label}
            } else {branch_label};
            let width = inner.width as usize;
            let mut show_date=true; let mut show_author=true; let mut show_hash=true;
            if width < 100{ show_hash=false; }
            if width < 82{ show_date=false; }
            if width < 72{ show_author=false; }
            let mut right_parts=Vec::new();
            if show_date{ right_parts.push(ci.date.clone()); }
            if show_author && !ci.author.is_empty(){
                let ad = if ci.author.len()>8{ci.author[..8].to_string()} else {ci.author.clone()};
                right_parts.push(ad);
            }
            if show_hash && !ci.short_hash.is_empty(){ right_parts.push(ci.short_hash.clone());}
            let right = right_parts.join("  ");
            let left_branch = if branch_label.is_empty(){String::new()} else {format!("{} ", branch_label)};
            let left_msg = ci.message.clone();
            let left_fixed = graph.chars().count() + left_branch.chars().count() + 2;
            let right_len = right.chars().count();
            let avail = if width > left_fixed + right_len + 4 { width - left_fixed - right_len -4 } else if width > left_fixed +4 {width - left_fixed -4} else {10};
            let trunc = if left_msg.chars().count() > avail { left_msg.chars().take(avail.saturating_sub(1)).collect::<String>() } else { left_msg.clone() };
            let mut spans=Vec::new();
            let gstyle = if is_sel{Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD)}else{Style::default().fg(Color::DarkGray)};
            spans.push(Span::styled(graph.clone(), gstyle));
            spans.push(Span::raw(" "));
            if !branch_label.is_empty(){
                let bl_style = if ci.branches.iter().any(|b| b.is_head){Style::default().fg(Color::Yellow)} else {Style::default().fg(Color::Green)};
                spans.push(Span::styled(branch_label.clone(), bl_style));
                spans.push(Span::raw(" "));
            }
            let mstyle = if is_sel{Style::default().fg(Color::White).bg(Color::DarkGray).add_modifier(Modifier::BOLD)}else{Style::default().fg(Color::White)};
            spans.push(Span::styled(trunc.clone(), mstyle));
            let left_len = graph.chars().count()+1+branch_label.chars().count()+ if branch_label.is_empty(){0} else {1} + trunc.chars().count();
            let pad = if width > left_len + right_len + 2 { width - left_len - right_len -2 } else {1};
            spans.push(Span::raw(" ".repeat(pad)));
            if show_date{ spans.push(Span::styled(ci.date.clone(), Style::default().fg(Color::DarkGray))); spans.push(Span::raw("  "));}
            if show_author && !ci.author.is_empty(){
                let ad = if ci.author.len()>8{ci.author[..8].to_string()} else {ci.author.clone()};
                spans.push(Span::styled(ad, Style::default().fg(Color::Cyan)));
