    except: pass
    try: proc.wait(timeout=1)
    except:
        try: proc.kill()
        except: pass
    try: os.close(master)
    except: pass
    return data
def render(data,w,h):
    screen=[[" " for _ in range(w)] for _ in range(h)]
    cur_r,cur_c=0,0
    s=data.decode("utf-8", errors="replace")
    pat=re.compile(r"\x1b\[([0-9;?]*)([A-Za-z])")
    idx=0
    while idx < len(s):
